#include <cstdint>
#include <vector>
#include "address.h"
#include "modules.h"

struct gen_fill_only_conservative_s2 : public champsim::modules::prefetcher {
    using prefetcher::prefetcher;

    std::vector<champsim::block_number> last_fill;

    uint32_t prefetcher_cache_operate(champsim::address addr, champsim::address ip,
                                     uint8_t cache_hit, bool useful_prefetch,
                                     access_type type, uint32_t metadata_in) {
        return metadata_in;
    }

    uint32_t prefetcher_cache_fill(champsim::address addr, long set, long way,
                                  uint8_t prefetch, champsim::address evicted_addr,
                                  uint32_t metadata_in) {
        champsim::block_number blk{addr};
        if (!prefetch) {
            last_fill.push_back(blk);
            if (last_fill.size() > 16)
                last_fill.erase(last_fill.begin());
        }

        for (const auto &entry : last_fill) {
            if (champsim::offset(entry, blk) == 1) {
                prefetch_line(champsim::address{blk + 1}, true, metadata_in);
                break;
            }
        }
        return metadata_in;
    }
};

